/* CHAP */

static void

handle_chap(netdissect_options *ndo,

            const u_char *p, int length)

{

	u_int code, len;

	int val_size, name_size, msg_size;

	const u_char *p0;

	int i;



	p0 = p;

	if (length < 1) {

		ND_PRINT((ndo, "[|chap]"));

		return;

	} else if (length < 4) {

		ND_TCHECK(*p);

		ND_PRINT((ndo, "[|chap 0x%02x]", *p));

		return;

	}



	ND_TCHECK(*p);

	code = *p;

	ND_PRINT((ndo, "CHAP, %s (0x%02x)",

               tok2str(chapcode_values,"unknown",code),

               code));

	p++;



	ND_TCHECK(*p);

	ND_PRINT((ndo, ", id %u", *p));		/* ID */

	p++;



	ND_TCHECK2(*p, 2);

	len = EXTRACT_16BITS(p);

	p += 2;



	/*

	 * Note that this is a generic CHAP decoding routine. Since we

	 * don't know which flavor of CHAP (i.e. CHAP-MD5, MS-CHAPv1,

	 * MS-CHAPv2) is used at this point, we can't decode packet

	 * specifically to each algorithms. Instead, we simply decode

	 * the GCD (Gratest Common Denominator) for all algorithms.

	 */

	switch (code) {

	case CHAP_CHAL:

	case CHAP_RESP:

		if (length - (p - p0) < 1)

			return;

		ND_TCHECK(*p);

		val_size = *p;		/* value size */

		p++;

		if (length - (p - p0) < val_size)

			return;

		ND_PRINT((ndo, ", Value "));

		for (i = 0; i < val_size; i++) {

			ND_TCHECK(*p);

			ND_PRINT((ndo, "%02x", *p++));

		}

		name_size = len - (p - p0);

		ND_PRINT((ndo, ", Name "));

		for (i = 0; i < name_size; i++) {

			ND_TCHECK(*p);

			safeputchar(ndo, *p++);

		}

		break;

	case CHAP_SUCC:

	case CHAP_FAIL:

		msg_size = len - (p - p0);

		ND_PRINT((ndo, ", Msg "));

		for (i = 0; i< msg_size; i++) {

			ND_TCHECK(*p);

			safeputchar(ndo, *p++);

		}

		break;

	}

	return;



trunc:

	ND_PRINT((ndo, "[|chap]"));

}



/* PAP (see RFC 1334) */

static void

handle_pap(netdissect_options *ndo,

           const u_char *p, int length)

{

	u_int code, len;

	int peerid_len, passwd_len, msg_len;

	const u_char *p0;

	int i;



	p0 = p;

	if (length < 1) {

		ND_PRINT((ndo, "[|pap]"));

		return;

	} else if (length < 4) {

		ND_TCHECK(*p);

		ND_PRINT((ndo, "[|pap 0x%02x]", *p));

		return;

	}



	ND_TCHECK(*p);

	code = *p;

	ND_PRINT((ndo, "PAP, %s (0x%02x)",

	          tok2str(papcode_values, "unknown", code),

	          code));

	p++;



	ND_TCHECK(*p);

	ND_PRINT((ndo, ", id %u", *p));		/* ID */

	p++;



	ND_TCHECK2(*p, 2);

	len = EXTRACT_16BITS(p);

	p += 2;



	if ((int)len > length) {

		ND_PRINT((ndo, ", length %u > packet size", len));

		return;

	}

	length = len;

	if (length < (p - p0)) {

		ND_PRINT((ndo, ", length %u < PAP header length", length));

		return;

	}



	switch (code) {

	case PAP_AREQ:

		if (length - (p - p0) < 1)

			return;

		ND_TCHECK(*p);

		peerid_len = *p;	/* Peer-ID Length */

		p++;

		if (length - (p - p0) < peerid_len)

			return;

		ND_PRINT((ndo, ", Peer "));

		for (i = 0; i < peerid_len; i++) {

			ND_TCHECK(*p);

			safeputchar(ndo, *p++);

		}



		if (length - (p - p0) < 1)

			return;

		ND_TCHECK(*p);

		passwd_len = *p;	/* Password Length */

		p++;

		if (length - (p - p0) < passwd_len)

			return;

		ND_PRINT((ndo, ", Name "));

		for (i = 0; i < passwd_len; i++) {

			ND_TCHECK(*p);

			safeputchar(ndo, *p++);

		}

		break;

	case PAP_AACK:

	case PAP_ANAK:

		if (length - (p - p0) < 1)

			return;

		ND_TCHECK(*p);

		msg_len = *p;		/* Msg-Length */

		p++;

		if (length - (p - p0) < msg_len)

			return;

		ND_PRINT((ndo, ", Msg "));

		for (i = 0; i< msg_len; i++) {

			ND_TCHECK(*p);

			safeputchar(ndo, *p++);

		}

		break;

	}

	return;



trunc:

	ND_PRINT((ndo, "[|pap]"));

}



