/* BACP config options */

static int

print_bacp_config_options(netdissect_options *ndo,

                          const u_char *p, int length)

{

	int len, opt;



	if (length < 2)

		return 0;

	ND_TCHECK2(*p, 2);

	len = p[1];

	opt = p[0];

	if (length < len)

		return 0;

	if (len < 2) {

		ND_PRINT((ndo, "\n\t  %s Option (0x%02x), length %u (length bogus, should be >= 2)",

		          tok2str(bacconfopts_values, "Unknown", opt),

		          opt,

		          len));

		return 0;

	}



	ND_PRINT((ndo, "\n\t  %s Option (0x%02x), length %u",

	          tok2str(bacconfopts_values, "Unknown", opt),

	          opt,

	          len));



	switch (opt) {

	case BACPOPT_FPEER:

		if (len != 6) {

			ND_PRINT((ndo, " (length bogus, should be = 6)"));

			return len;

		}

		ND_TCHECK2(*(p + 2), 4);

		ND_PRINT((ndo, ": Magic-Num 0x%08x", EXTRACT_32BITS(p + 2)));

		break;

	default:

		/*

		 * Unknown option; dump it as raw bytes now if we're

		 * not going to do so below.

		 */

		if (ndo->ndo_vflag < 2)

			print_unknown_data(ndo, &p[2], "\n\t    ", len - 2);

		break;

	}

	if (ndo->ndo_vflag > 1)

		print_unknown_data(ndo, &p[2], "\n\t    ", len - 2); /* exclude TLV header */



	return len;



trunc:

	ND_PRINT((ndo, "[|bacp]"));

	return 0;

}



static void

ppp_hdlc(netdissect_options *ndo,

         const u_char *p, int length)

{

	u_char *b, *t, c;

	const u_char *s;

	int i, proto;

	const void *se;



        if (length <= 0)

                return;



	b = (u_char *)malloc(length);

	if (b == NULL)

		return;



	/*

	 * Unescape all the data into a temporary, private, buffer.

	 * Do this so that we dont overwrite the original packet

	 * contents.

	 */

	for (s = p, t = b, i = length; i > 0 && ND_TTEST(*s); i--) {

		c = *s++;

		if (c == 0x7d) {

			if (i <= 1 || !ND_TTEST(*s))

				break;

			i--;

			c = *s++ ^ 0x20;

		}

		*t++ = c;

	}



	se = ndo->ndo_snapend;

	ndo->ndo_snapend = t;

	length = t - b;



        /* now lets guess about the payload codepoint format */

        if (length < 1)

                goto trunc;

        proto = *b; /* start with a one-octet codepoint guess */



        switch (proto) {

        case PPP_IP:

		ip_print(ndo, b + 1, length - 1);

		goto cleanup;

        case PPP_IPV6:

		ip6_print(ndo, b + 1, length - 1);

		goto cleanup;

        default: /* no luck - try next guess */

		break;

        }



        if (length < 2)

                goto trunc;

        proto = EXTRACT_16BITS(b); /* next guess - load two octets */



        switch (proto) {

        case (PPP_ADDRESS << 8 | PPP_CONTROL): /* looks like a PPP frame */

            if (length < 4)

                goto trunc;

            proto = EXTRACT_16BITS(b+2); /* load the PPP proto-id */

            handle_ppp(ndo, proto, b + 4, length - 4);

            break;

        default: /* last guess - proto must be a PPP proto-id */

            handle_ppp(ndo, proto, b + 2, length - 2);

            break;

        }



cleanup:

	ndo->ndo_snapend = se;

	free(b);

        return;



trunc:

	ndo->ndo_snapend = se;

	free(b);

	ND_PRINT((ndo, "[|ppp]"));

}





/* PPP */

static void

handle_ppp(netdissect_options *ndo,

           u_int proto, const u_char *p, int length)

{

	if ((proto & 0xff00) == 0x7e00) { /* is this an escape code ? */

		ppp_hdlc(ndo, p - 1, length);

		return;

	}



	switch (proto) {

	case PPP_LCP: /* fall through */

	case PPP_IPCP:

	case PPP_OSICP:

	case PPP_MPLSCP:

	case PPP_IPV6CP:

	case PPP_CCP:

	case PPP_BACP:

		handle_ctrl_proto(ndo, proto, p, length);

		break;

	case PPP_ML:

		handle_mlppp(ndo, p, length);

		break;

	case PPP_CHAP:

		handle_chap(ndo, p, length);

		break;

	case PPP_PAP:

		handle_pap(ndo, p, length);

		break;

	case PPP_BAP:		/* XXX: not yet completed */

		handle_bap(ndo, p, length);

		break;

	case ETHERTYPE_IP:	/*XXX*/

        case PPP_VJNC:

	case PPP_IP:

		ip_print(ndo, p, length);

		break;

	case ETHERTYPE_IPV6:	/*XXX*/

	case PPP_IPV6:

		ip6_print(ndo, p, length);

		break;

	case ETHERTYPE_IPX:	/*XXX*/

	case PPP_IPX:

		ipx_print(ndo, p, length);

		break;

	case PPP_OSI:

		isoclns_print(ndo, p, length, length);

		break;

	case PPP_MPLS_UCAST:

	case PPP_MPLS_MCAST:

		mpls_print(ndo, p, length);

		break;

	case PPP_COMP:

		ND_PRINT((ndo, "compressed PPP data"));

		break;

	default:

		ND_PRINT((ndo, "%s ", tok2str(ppptype2str, "unknown PPP protocol (0x%04x)", proto)));

		print_unknown_data(ndo, p, "\n\t", length);

		break;

	}

}



/* Standard PPP printer */

u_int

ppp_print(netdissect_options *ndo,

          register const u_char *p, u_int length)

{

	u_int proto,ppp_header;

        u_int olen = length; /* _o_riginal length */

	u_int hdr_len = 0;



	/*

	 * Here, we assume that p points to the Address and Control

	 * field (if they present).

	 */

	if (length < 2)

		goto trunc;

	ND_TCHECK2(*p, 2);

        ppp_header = EXTRACT_16BITS(p);



        switch(ppp_header) {

        case (PPP_WITHDIRECTION_IN  << 8 | PPP_CONTROL):

            if (ndo->ndo_eflag) ND_PRINT((ndo, "In  "));

            p += 2;

            length -= 2;

            hdr_len += 2;

            break;

        case (PPP_WITHDIRECTION_OUT << 8 | PPP_CONTROL):

            if (ndo->ndo_eflag) ND_PRINT((ndo, "Out "));

            p += 2;

            length -= 2;

            hdr_len += 2;

            break;

        case (PPP_ADDRESS << 8 | PPP_CONTROL):

            p += 2;			/* ACFC not used */

            length -= 2;

            hdr_len += 2;

            break;



        default:

            break;

        }



	if (length < 2)

		goto trunc;

	ND_TCHECK(*p);

	if (*p % 2) {

		proto = *p;		/* PFC is used */

		p++;

		length--;

		hdr_len++;

	} else {

		ND_TCHECK2(*p, 2);

		proto = EXTRACT_16BITS(p);

		p += 2;

		length -= 2;

		hdr_len += 2;

	}



	if (ndo->ndo_eflag)

		ND_PRINT((ndo, "%s (0x%04x), length %u: ",

		          tok2str(ppptype2str, "unknown", proto),

		          proto,

		          olen));



	handle_ppp(ndo, proto, p, length);

	return (hdr_len);

trunc:

	ND_PRINT((ndo, "[|ppp]"));

	return (0);

}





