#define foreach_grant_safe(pos, n, rbtree, node) \

	for ((pos) = container_of(rb_first((rbtree)), typeof(*(pos)), node), \

	     (n) = (&(pos)->node != NULL) ? rb_next(&(pos)->node) : NULL; \

	     &(pos)->node != NULL; \

